args<-commandArgs(TRUE); P<-normalizePath(args[1]);W<-file.path(P,'work/2026-10-29-bulk-omics-reproduction/motrpac');D<-file.path(P,'data/raw/topjournal-bulk-20261029/motrpac');PD<-file.path(P,'results/plot_data');stem<-'motrpac_temporal_network_20261029'
load(file.path(D,'GRAPH_COMPONENTS.rda'));load(file.path(D,'GRAPH_STATES.rda'));source(file.path(D,'bayesian_graphical_clustering.R'))
cols<-c(ACETYL='#A982C5',PHOSPHO='#EDAA46',PROT='#35A898',TRNSCRPT='#548BC1');states<-c('F1_M0','F1_M1','F0_M1','F0_M0','F-1_M0','F-1_M-1','F0_M-1');labs<-c('F only up','Both up','M only up','No change','F only down','Both down','M only down'); tissues<-c('SKM-GN','SKM-VL','HEART');N<-E<-T<-list();features<-list()
for(tissue in tissues){
 omes<-if(tissue=='SKM-VL')'TRNSCRPT' else names(cols);d<-GRAPH_STATES[GRAPH_STATES$tissue==tissue & GRAPH_STATES$ome%in%omes,];features[[tissue]]<-d
 filt<-function(x)lapply(x,function(v)intersect(v,d$feature)); ns<-filt(GRAPH_COMPONENTS$node_sets);es<-filt(GRAPH_COMPONENTS$edge_sets);top<-get_trajectory_sizes_from_edge_sets(es,min_size=5)[1:3,];top$tissue<-tissue;T[[tissue]]<-top; kept<-filter_edge_sets_by_trajectories(es,topk=3,min_path_size=5)
 n<-data.frame(node=names(ns),count=lengths(ns),tissue=tissue);n$state<-sub('^[^_]+_','',n$node);n$week<-as.numeric(sub('w.*','',n$node));n$y<-8-match(n$state,states);n$label<-labs[match(n$state,states)];n$displayed<-n$state%in%states;n$direction<-ifelse(grepl('up',n$label),'Up',ifelse(grepl('down',n$label),'Down','No change'));N[[tissue]]<-n
 ee<-do.call(rbind,lapply(names(kept),function(id){p<-strsplit(id,'---',fixed=TRUE)[[1]];data.frame(tissue=tissue,edge=id,source=p[1],target=p[2],ome=omes,count=vapply(omes,function(o)sum(startsWith(kept[[id]],paste0(o,';'))),numeric(1)),stringsAsFactors=FALSE)}));ee$displayed<-ee$count>=20;ee$color<-cols[ee$ome]; E[[tissue]]<-ee
}
write.csv(do.call(rbind,N),file.path(PD,paste0(stem,'_nodes.csv')),row.names=FALSE);write.csv(do.call(rbind,E),file.path(PD,paste0(stem,'_edges.csv')),row.names=FALSE);write.csv(do.call(rbind,T),file.path(PD,paste0(stem,'_top_paths.csv')),row.names=FALSE);write.csv(do.call(rbind,features),file.path(PD,paste0(stem,'_features.csv')),row.names=FALSE)
jsonlite::write_json(list(status='PASS',source='author processed GRAPH_STATES and GRAPH_COMPONENTS',feature_counts=lapply(features,nrow),top_paths=T,display_node_counts=lapply(N,function(n)sum(n$displayed)),display_edge_counts=lapply(E,function(e)sum(e$displayed)),ome_edge_min_count=20,top_paths_per_tissue=3,simulation=FALSE,scope='Nature2024 Fig4a full three-tissue graphical panel;not Fig4b-d',source_version='downloaded author repository snapshots;hash bound'),file.path(W,'input-qc.json'),pretty=TRUE,auto_unbox=TRUE)
